// Bundle the iOS (Scriptable) core: src/schedule.js + ios/src/widget.js -> ios/core.js
// One self-contained file, so the phones never depend on desktop sources at runtime.
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const schedule = fs.readFileSync(path.join(root, 'src/schedule.js'), 'utf8');
const widget = fs.readFileSync(path.join(root, 'ios/src/widget.js'), 'utf8');
const out = [
  '// Svitlo for Scriptable — GENERATED by scripts/build-ios.js, do not edit. Sources: src/schedule.js, ios/src/widget.js',
  '// https://github.com/vladyslav-deda/svitlo-widget',
  "const S = (function () { const module = { exports: {} };",
  schedule,
  'return module.exports; })();',
  '',
  widget,
  '// SVITLO_CORE_END',
  '',
].join('\n');
fs.writeFileSync(path.join(root, 'ios/core.js'), out);
console.log('ios/core.js', out.length, 'bytes');
